1	//! Audio recording: save, transcription queue (local Whisper, AssemblyAI, or a
2	//! shell-registered provider), listing.
3	
4	use crate::AppEnv;
5	use serde::{Deserialize, Serialize};
6	use std::{
7	    collections::{HashSet, VecDeque},
8	    fs,
9	    path::{Path, PathBuf},
10	    sync::{Arc, Mutex, OnceLock},
11	    thread,
12	};
13	use uuid::Uuid;
14	
15	use crate::ports::recordings::{RecordingsGateway, TranscriptionProvider};
16	use crate::{
17	    allocate_note_file_name, collect_markdown_note_files, decode_audio_base64, generate_note_id,
18	    is_storage_folder_path, note_parent_folder_path, notes_root, now_ms, parse_note_front_matter,
19	    resolve_path, sanitize_relative, strip_root, uuid_tail_without_timestamp_prefix,
20	    write_note_with_front_matter, NoteFileNameFormat, NoteFrontMatter, BASE64, FEED_FOLDER,
21	    LEGACY_RECORDINGS_FOLDER, RECORDINGS_STORAGE_FOLDER, RECORDING_STATUS_COMPLETED,
22	    RECORDING_STATUS_FAILED, RECORDING_STATUS_PENDING, RECORDING_STATUS_PROCESSING,
23	};
24	use base64::Engine as _;
25	
26	// Transcription backends — the worker below dispatches to whichever the job
27	// selects (local Whisper on desktop, AssemblyAI on iOS).
28	mod assembly;
29	mod whisper;
30	pub use assembly::transcribe_audio_bytes_with_assembly;
31	pub use whisper::{
32	    check_whisper_availability, save_word_level_json, transcribe_audio_local_whisper,
33	};
34	
35	// ── Constants ──────────────────────────────────────────────────────────────────
36	
37	const AUDIO_FILE_NAME_PREFIX: &str = "audio";
38	pub const RECORDING_FRONTMATTER_TYPE: &str = "audio_recording";
39	
40	pub const DEFAULT_WHISPER_MODEL: &str = "large-v3";
41	
42	// ── Types ──────────────────────────────────────────────────────────────────────
43	
44	/// Arguments for saving a new audio recording to disk.
45	#[derive(Deserialize)]
46	pub struct SaveRecordingArgs {
47	    pub audio_base64: String,
48	    pub mime_type: Option<String>,
49	    pub folder_path: Option<String>,
50	    #[serde(default)]
51	    pub file_name_format: NoteFileNameFormat,
52	}
53	
54	/// Paths returned after successfully writing a recording note and audio file.
55	#[derive(Serialize)]
56	pub struct RecordingWriteResult {
57	    pub folder_path: String,
58	    pub note_path: String,
59	    pub audio_path: String,
60	}
61	
62	/// Arguments for queuing transcription via AssemblyAI.
63	#[derive(Deserialize)]
64	pub struct QueueRecordingsArgs {
65	    pub assembly_api_key: Option<String>,
66	}
67	
68	/// Arguments for queuing transcription via local Whisper.
69	#[derive(Deserialize)]
70	pub struct QueueLocalTranscriptionsArgs {
71	    pub model: Option<String>,
72	}
73	
74	/// Arguments for re-triggering a single note's transcription.
75	#[derive(Deserialize)]
76	pub struct RetriggerTranscriptionArgs {
77	    pub note_path: String,
78	    pub model: Option<String>,
79	}
80	
81	#[derive(Deserialize)]
82	pub struct CheckWhisperStatusArgs {
83	    pub model: Option<String>,
84	    /// When true, provision the managed env (and download the model) instead of
85	    /// only probing readiness. Driven by the explicit "Set up" button.
86	    #[serde(default)]
87	    pub setup: bool,
88	}
89	
90	/// Summary returned after scanning and queuing recording notes for transcription.
91	#[derive(Serialize)]
92	pub struct RecordingTranscriptionQueueResult {
93	    pub scanned: usize,
94	    pub queued: usize,
95	    pub skipped: usize,
96	    pub in_flight: usize,
97	}
98	
99	/// Current state of the transcription worker queue.
100	#[derive(Serialize)]
101	pub struct RecordingQueueSnapshot {
102	    pub running: bool,
103	    pub current_recording: Option<String>,
104	    pub pending: Vec<String>,
105	    pub in_flight: usize,
106	}
107	
108	/// Single recording entry for the frontend recordings list.
109	#[derive(Serialize)]
110	pub struct RecordingListItem {
111	    pub note_path: String,
112	    pub folder_path: String,
113	    pub audio_path: Option<String>,
114	    pub status: String,
115	    pub error: Option<String>,
116	    pub updated_ms: Option<i64>,
117	    pub is_queued: bool,
118	    pub is_processing: bool,
119	}
120	
121	/// Combined queue snapshot and recordings list for the frontend.
122	#[derive(Serialize)]
123	pub struct RecordingsListResult {
124	    pub queue: RecordingQueueSnapshot,
125	    pub recordings: Vec<RecordingListItem>,
126	}
127	
128	/// Arguments for reading a recording's raw audio bytes.
129	#[derive(Deserialize)]
130	pub struct ReadRecordingAudioArgs {
131	    pub path: String,
132	}
133	
134	/// Base64-encoded audio data with MIME type, returned to the frontend.
135	#[derive(Serialize)]
136	pub struct RecordingAudioPayload {
137	    pub mime_type: String,
138	    pub audio_base64: String,
139	}
140	
141	/// Platform native recorder availability and state.
142	#[derive(Serialize)]
143	pub struct NativeRecorderCapabilities {
144	    pub supported: bool,
145	    pub recording: bool,
146	    pub started_ms: Option<i64>,
147	}
148	
149	/// Local Whisper availability check result.
150	#[derive(Serialize)]
151	pub struct WhisperStatusResult {
152	    pub available: bool,
153	    pub python_found: bool,
154	    pub error: Option<String>,
155	}
156	
157	/// Determines which transcription backend to use for a queued job.
158	#[derive(Clone)]
159	pub enum TranscriptionMethod {
160	    AssemblyAi {
161	        api_key: String,
162	    },
163	    /// Local faster-whisper running in the app-managed Python environment.
164	    /// Carries an `AppEnv` so the worker can provision the env lazily.
165	    LocalWhisper {
166	        model: String,
167	        app: AppEnv,
168	    },
169	    /// A shell-registered [`TranscriptionProvider`] — e.g. native on-device
170	    /// speech recognition plugged in through the mobile FFI.
171	    Provider {
172	        provider: Arc<dyn TranscriptionProvider>,
173	    },
174	}
175	
176	/// A single pending transcription job in the queue.
177	#[derive(Clone)]
178	pub struct QueuedTranscriptionJob {
179	    pub note_rel: String,
180	    pub note_path: PathBuf,
181	    pub audio_path: PathBuf,
182	    pub method: TranscriptionMethod,
183	}
184	
185	/// Core recordings gateway. It owns native-recorder state, note/audio
186	/// filesystem writes, and background transcription queue mutation.
187	pub struct RecordingsAdapter {
188	    app: AppEnv,
189	}
190	
191	impl RecordingsAdapter {
192	    pub fn new(app: AppEnv) -> Self {
193	        Self { app }
194	    }
195	
196	    /// Queue pending recordings for a shell-registered transcription provider.
197	    /// Not part of [`RecordingsGateway`] — only shells that register a provider
198	    /// (the mobile FFI) call this.
199	    pub fn queue_with_provider(
200	        &self,
201	        provider: Arc<dyn TranscriptionProvider>,
202	    ) -> Result<RecordingTranscriptionQueueResult, String> {
203	        let root = crate::ensured_notes_root(&self.app)?;
204	        queue_recordings_for_provider_transcription(&root, provider)
205	    }
206	}
207	
208	impl RecordingsGateway for RecordingsAdapter {
209	    type NativeCapabilities = NativeRecorderCapabilities;
210	    type AudioPayload = RecordingAudioPayload;
211	    type SaveArgs = SaveRecordingArgs;
212	    type WriteResult = RecordingWriteResult;
213	    type CloudQueueArgs = QueueRecordingsArgs;
214	    type LocalQueueArgs = QueueLocalTranscriptionsArgs;
215	    type QueueResult = RecordingTranscriptionQueueResult;
216	    type RetriggerArgs = RetriggerTranscriptionArgs;
217	    type WhisperArgs = CheckWhisperStatusArgs;
218	    type WhisperStatus = WhisperStatusResult;
219	    type ListResult = RecordingsListResult;
220	    type ReadArgs = ReadRecordingAudioArgs;
221	
222	    // Native capture is a shell concern: the Tauri iOS shell wraps this adapter
223	    // and overrides the three native_* methods with AVAudioRecorder; React
224	    // Native records through its own audio module and only calls save().
225	    fn native_capabilities(&self) -> Result<Self::NativeCapabilities, String> {
226	        Ok(NativeRecorderCapabilities {
227	            supported: false,
228	            recording: false,
229	            started_ms: None,
230	        })
231	    }
232	
233	    fn start_native(&self) -> Result<(), String> {
234	        Err("Native iOS audio recorder is unavailable on this platform.".to_string())
235	    }
236	
237	    fn stop_native(&self) -> Result<Self::AudioPayload, String> {
238	        Err("Native iOS audio recorder is unavailable on this platform.".to_string())
239	    }
240	
241	    fn save(&self, args: Self::SaveArgs) -> Result<Self::WriteResult, String> {
242	        let root = crate::ensured_notes_root(&self.app)?;
243	        let audio_bytes = decode_audio_base64(&args.audio_base64)?;
244	        if audio_bytes.is_empty() {
245	            return Err("Audio payload is empty.".to_string());
246	        }
247	
248	        let (target_folder_rel, target_folder_path) =
249	            resolve_recording_target_folder(&self.app, args.folder_path.as_deref())?;
250	        let extension = audio_extension_from_mime(args.mime_type.as_deref());
251	        let audio_path = recording_audio_file_path(&root, extension)?;
252	        fs::write(&audio_path, audio_bytes).map_err(|error| error.to_string())?;
253	
254	        let now = now_ms().unwrap_or(0);
255	        let note_id = generate_note_id();
256	        let note_file_name =
257	            recording_note_file_name(&target_folder_path, now, &note_id, args.file_name_format)?;
258	        let note_path = target_folder_path.join(&note_file_name);
259	        let mut meta = NoteFrontMatter::default();
260	        meta.id = Some(note_id);
261	        meta.created_ms = Some(now);
262	        meta.updated_ms = Some(now);
263	        meta.note_type = Some(RECORDING_FRONTMATTER_TYPE.to_string());
264	        meta.recording_audio_path = Some(strip_root(&root, &audio_path));
265	        meta.transcription_status = Some(RECORDING_STATUS_PENDING.to_string());
266	        meta.transcription_error = None;
267	        meta.transcription_updated_ms = Some(now);
268	        meta.transcription_id = None;
269	
270	        write_note_with_front_matter(&note_path, &meta, &recording_initial_body())?;
271	        if !crate::is_feed_folder_path(&root, &target_folder_path) {
272	            crate::update_order_append(&target_folder_path, &[note_file_name], false)?;
273	        }
274	
275	        Ok(RecordingWriteResult {
276	            folder_path: target_folder_rel,
277	            note_path: strip_root(&root, &note_path),
278	            audio_path: strip_root(&root, &audio_path),
279	        })
280	    }
281	
282	    fn queue_cloud(&self, args: Self::CloudQueueArgs) -> Result<Self::QueueResult, String> {
283	        let app_data = crate::app_data_dir(&self.app)?;
284	        let app_config = crate::load_app_config(&app_data);
285	
286	        let api_key = args
287	            .assembly_api_key
288	            .as_deref()
289	            .filter(|s| !s.is_empty())
290	            .unwrap_or(app_config.assemblyai_api_key.as_str())
291	            .trim();
292	
293	        if api_key.is_empty() {
294	            return Err("AssemblyAI API key is required.".to_string());
295	        }
296	
297	        let root = crate::ensured_notes_root(&self.app)?;
298	        queue_recordings_with_method(
299	            &root,
300	            &TranscriptionMethod::AssemblyAi {
301	                api_key: api_key.to_string(),
302	            },
303	        )
304	    }
305	
306	    fn queue_local(&self, args: Self::LocalQueueArgs) -> Result<Self::QueueResult, String> {
307	        let app_data = crate::app_data_dir(&self.app)?;
308	        let app_config = crate::load_app_config(&app_data);
309	
310	        let model = args
311	            .model
312	            .as_deref()
313	            .filter(|s| !s.is_empty())
314	            .unwrap_or(app_config.whisper_model.as_str())
315	            .trim();
316	
317	        if model.is_empty() {
318	            return Err("Whisper model is required.".to_string());
319	        }
320	
321	        let root = crate::ensured_notes_root(&self.app)?;
322	        queue_recordings_for_local_transcription(&self.app, &root, model)
323	    }
324	
325	    fn retrigger(&self, args: Self::RetriggerArgs) -> Result<(), String> {
326	        let root = crate::ensured_notes_root(&self.app)?;
327	        let note_rel = args.note_path.trim();
328	        if note_rel.is_empty() {
329	            return Err("Note path is required.".to_string());
330	        }
331	        let model = args.model.as_deref().unwrap_or(DEFAULT_WHISPER_MODEL);
332	        retrigger_single_transcription(&self.app, &root, note_rel, model)
333	    }
334	
335	    fn whisper_status(&self, args: Self::WhisperArgs) -> Self::WhisperStatus {
336	        check_whisper_availability(&self.app, args.model.as_deref(), args.setup)
337	    }
338	
339	    fn list(&self) -> Result<Self::ListResult, String> {
340	        let root = crate::ensured_notes_root(&self.app)?;
341	        let queue = recording_queue_snapshot();
342	        let pending_set = queue
343	            .pending
344	            .iter()
345	            .map(String::as_str)
346	            .collect::<HashSet<_>>();
347	
348	        let mut recordings = collect_recording_notes(&root)?
349	            .into_iter()
350	            .map(|recording| {
351	                let folder_path = note_parent_folder_path(&recording.note_rel);
352	                let audio_exists = recording.audio_path.exists();
353	                let mut error = recording.error.clone();
354	                if !audio_exists {
355	                    error = Some("Audio file is missing.".to_string());
356	                }
357	                RecordingListItem {
358	                    note_path: recording.note_rel.clone(),
359	                    folder_path,
360	                    audio_path: if audio_exists {
361	                        Some(recording.audio_rel.clone())
362	                    } else {
363	                        None
364	                    },
365	                    status: recording.status.clone(),
366	                    error,
367	                    updated_ms: recording.updated_ms,
368	                    is_queued: pending_set.contains(recording.note_rel.as_str()),
369	                    is_processing: queue.current_recording.as_deref()
370	                        == Some(recording.note_rel.as_str()),
371	                }
372	            })
373	            .collect::<Vec<_>>();
374	
375	        recordings.sort_by(|a, b| b.updated_ms.unwrap_or(0).cmp(&a.updated_ms.unwrap_or(0)));
376	        Ok(RecordingsListResult { queue, recordings })
377	    }
378	
379	    fn read_audio(&self, args: Self::ReadArgs) -> Result<Self::AudioPayload, String> {
380	        let root = crate::ensured_notes_root(&self.app)?;
381	        let path_rel = sanitize_relative(&args.path)?;
382	        let audio_path = root.join(path_rel);
383	        if !is_recording_audio_path_allowed(&root, &audio_path) {
384	            return Err("Only files inside recordings storage are allowed.".to_string());
385	        }
386	        if !audio_path.exists() || !audio_path.is_file() {
387	            return Err("Audio file not found.".to_string());
388	        }
389	        let bytes = fs::read(&audio_path).map_err(|error| error.to_string())?;
390	        Ok(RecordingAudioPayload {
391	            mime_type: audio_mime_from_path(&audio_path).to_string(),
392	            audio_base64: BASE64.encode(bytes),
393	        })
394	    }
395	}
396	
397	/// Parsed info for a recording note found during scanning.
398	#[derive(Clone)]
399	pub struct RecordingNoteInfo {
400	    pub note_rel: String,
401	    pub note_path: PathBuf,
402	    pub audio_rel: String,
403	    pub audio_path: PathBuf,
404	    pub status: String,
405	    pub error: Option<String>,
406	    pub updated_ms: Option<i64>,
407	}
408	
409	/// In-memory state for the background transcription worker.
410	#[derive(Default)]
411	pub struct TranscriptionQueueState {
412	    pub running: bool,
413	    pub current_recording: Option<String>,
414	    pub pending: VecDeque<QueuedTranscriptionJob>,
415	    pub known_recordings: HashSet<String>,
416	}
417	
418	// ── Static ─────────────────────────────────────────────────────────────────────
419	
420	static TRANSCRIPTION_QUEUE: OnceLock<Mutex<TranscriptionQueueState>> = OnceLock::new();
421	
422	// ── Queue state ────────────────────────────────────────────────────────────────
423	
424	/// Access the global transcription queue mutex.
425	pub fn transcription_queue_state() -> &'static Mutex<TranscriptionQueueState> {
426	    TRANSCRIPTION_QUEUE.get_or_init(|| Mutex::new(TranscriptionQueueState::default()))
427	}
428	
429	/// Collect note paths that are currently queued or being transcribed.
430	pub fn active_transcription_note_paths() -> HashSet<String> {
431	    let queue = transcription_queue_state();
432	    let state = queue.lock().expect("transcription queue poisoned");
433	    let mut active = HashSet::with_capacity(state.pending.len() + 1);
434	    if let Some(current) = &state.current_recording {
435	        active.insert(current.clone());
436	    }
437	    active.extend(state.pending.iter().map(|job| job.note_rel.clone()));
438	    active
439	}
440	
441	/// Snapshot the current queue state for the frontend.
442	pub fn recording_queue_snapshot() -> RecordingQueueSnapshot {
443	    let queue = transcription_queue_state();
444	    let state = queue.lock().expect("transcription queue poisoned");
445	    let pending = state
446	        .pending
447	        .iter()
448	        .map(|job| job.note_rel.clone())
449	        .collect::<Vec<_>>();
450	    RecordingQueueSnapshot {
451	        running: state.running,
452	        current_recording: state.current_recording.clone(),
453	        in_flight: pending.len() + usize::from(state.running),
454	        pending,
455	    }
456	}
457	
458	// ── Audio helpers ──────────────────────────────────────────────────────────────
459	
460	/// Map a MIME type to a file extension (defaults to "webm").
461	pub fn audio_extension_from_mime(mime_type: Option<&str>) -> &'static str {
462	    let Some(raw) = mime_type else {
463	        return "webm";
464	    };
465	    let normalized = raw.to_lowercase();
466	    if normalized.contains("mp4") || normalized.contains("aac") {
467	        return "m4a";
468	    }
469	    if normalized.contains("mpeg") || normalized.contains("mp3") {
470	        return "mp3";
471	    }
472	    if normalized.contains("wav") {
473	        return "wav";
474	    }
475	    if normalized.contains("ogg") {
476	        return "ogg";
477	    }
478	    if normalized.contains("flac") {
479	        return "flac";
480	    }
481	    "webm"
482	}
483	
484	/// Infer MIME type from an audio file's extension.
485	pub fn audio_mime_from_path(path: &Path) -> &'static str {
486	    let ext = path
487	        .extension()
488	        .and_then(|value| value.to_str())
489	        .unwrap_or("")
490	        .to_lowercase();
491	    match ext.as_str() {
492	        "m4a" => "audio/mp4",
493	        "mp3" => "audio/mpeg",
494	        "wav" => "audio/wav",
495	        "ogg" => "audio/ogg",
496	        "webm" => "audio/webm",
497	        "aac" => "audio/aac",
498	        "mp4" => "audio/mp4",
499	        "flac" => "audio/flac",
500	        _ => "application/octet-stream",
501	    }
502	}
503	
504	/// Build the note body for a recording (transcript text or empty).
505	fn recording_note_body(status: &str, transcript: Option<&str>) -> String {
506	    if status != RECORDING_STATUS_COMPLETED {
507	        return String::new();
508	    }
509	    let value = transcript.unwrap_or_default().trim();
510	    if value.is_empty() {
511	        String::new()
512	    } else {
513	        format!("{}\n", value)
514	    }
515	}
516	
517	fn recording_storage_root(root: &Path) -> PathBuf {
518	    root.join(RECORDINGS_STORAGE_FOLDER)
519	}
520	
521	/// Verify that an audio path resolves inside the allowed storage folders.
522	pub fn is_recording_audio_path_allowed(root: &Path, audio_path: &Path) -> bool {
523	    audio_path.starts_with(recording_storage_root(root))
524	        || audio_path.starts_with(root.join(LEGACY_RECORDINGS_FOLDER))
525	}
526	
527	// ── Note scanning ──────────────────────────────────────────────────────────────
528	
529	fn recording_info_from_note_meta(
530	    root: &Path,
531	    note_path: &Path,
532	    note_rel: &str,
533	    meta: &NoteFrontMatter,
534	) -> Option<RecordingNoteInfo> {
535	    if meta.note_type.as_deref() != Some(RECORDING_FRONTMATTER_TYPE) {
536	        return None;
537	    }
538	    let audio_rel = meta.recording_audio_path.as_ref()?.trim();
539	    if audio_rel.is_empty() {
540	        return None;
541	    }
542	    let audio_rel_path = sanitize_relative(audio_rel).ok()?;
543	    let audio_path = root.join(&audio_rel_path);
544	    if !is_recording_audio_path_allowed(root, &audio_path) {
545	        return None;
546	    }
547	    let status = meta
548	        .transcription_status
549	        .as_deref()
550	        .unwrap_or(RECORDING_STATUS_PENDING)
551	        .to_string();
552	    Some(RecordingNoteInfo {
553	        note_rel: note_rel.to_string(),
554	        note_path: note_path.to_path_buf(),
555	        audio_rel: audio_rel_path.to_string_lossy().replace('\\', "/"),
556	        audio_path,
557	        status,
558	        error: meta.transcription_error.clone(),
559	        updated_ms: meta.transcription_updated_ms.or(meta.updated_ms),
560	    })
561	}
562	
563	/// Scan all markdown notes and extract recording metadata.
564	pub fn collect_recording_notes(root: &Path) -> Result<Vec<RecordingNoteInfo>, String> {
565	    let mut note_files = Vec::new();
566	    collect_markdown_note_files(root, root, &mut note_files)?;
567	    let mut recordings = Vec::new();
568	    for note_path in note_files {
569	        let raw = match fs::read_to_string(&note_path) {
570	            Ok(value) => value,
571	            Err(_) => continue,
572	        };
573	        let (meta, _) = parse_note_front_matter(&raw);
574	        let note_rel = strip_root(root, &note_path);
575	        if let Some(info) = recording_info_from_note_meta(root, &note_path, &note_rel, &meta) {
576	            recordings.push(info);
577	        }
578	    }
579	    Ok(recordings)
580	}
581	
582	/// Update a recording note's transcription status and body on disk.
583	pub fn update_recording_note_status(
584	    note_path: &Path,
585	    status: &str,
586	    error: Option<String>,
587	    transcript_id: Option<String>,
588	    transcript_text: Option<&str>,
589	) -> Result<(), String> {
590	    let raw = fs::read_to_string(note_path).map_err(|issue| issue.to_string())?;
591	    let (mut meta, _) = parse_note_front_matter(&raw);
592	    if meta.id.is_none() {
593	        meta.id = Some(generate_note_id());
594	    }
595	    let now = now_ms();
596	    if meta.created_ms.is_none() {
597	        meta.created_ms = now;
598	    }
599	    meta.updated_ms = now.or(meta.updated_ms);
600	    meta.note_type = Some(RECORDING_FRONTMATTER_TYPE.to_string());
601	    meta.transcription_status = Some(status.to_string());
602	    meta.transcription_error = error.clone();
603	    meta.transcription_updated_ms = now.or(meta.transcription_updated_ms);
604	    meta.transcription_id = transcript_id;
605	    let next_body = recording_note_body(status, transcript_text);
606	    write_note_with_front_matter(note_path, &meta, &next_body)
607	}
608	
609	// ── Worker ─────────────────────────────────────────────────────────────────────
610	
611	fn process_transcription_job(job: QueuedTranscriptionJob) {
612	    if let Err(error) = update_recording_note_status(
613	        &job.note_path,
614	        RECORDING_STATUS_PROCESSING,
615	        None,
616	        None,
617	        None,
618	    ) {
619	        eprintln!(
620	            "[recordings] failed to mark processing for {}: {}",
621	            job.note_rel, error
622	        );
623	    }
624	
625	    let result = match &job.method {
626	        TranscriptionMethod::LocalWhisper { model, app } => {
627	            // Provision the managed Python env on first use; subsequent jobs are
628	            // instant. Any setup failure surfaces as the note's transcription error.
629	            match crate::ensure_whisper_env(app) {
630	                Ok(python) => transcribe_audio_local_whisper(&job.audio_path, model, &python),
631	                Err(error) => Err(format!("Failed to set up local transcription: {error}")),
632	            }
633	        }
634	        TranscriptionMethod::AssemblyAi { api_key } => {
635	            let audio_bytes = match fs::read(&job.audio_path) {
636	                Ok(bytes) => bytes,
637	                Err(e) => {
638	                    let _ = update_recording_note_status(
639	                        &job.note_path,
640	                        RECORDING_STATUS_FAILED,
641	                        Some(e.to_string()),
642	                        None,
643	                        None,
644	                    );
645	                    eprintln!(
646	                        "[recordings] failed to read audio for {}: {}",
647	                        job.note_rel, e
648	                    );
649	                    return;
650	                }
651	            };
652	            transcribe_audio_bytes_with_assembly(audio_bytes, api_key)
653	        }
654	        TranscriptionMethod::Provider { provider } => provider
655	            .transcribe(&job.audio_path)
656	            .map(|transcript| (transcript, String::new()))
657	            .map_err(|error| format!("{} transcription failed: {}", provider.id(), error)),
658	    };
659	
660	    match result {
661	        Ok((transcript, id_or_json)) => {
662	            // For local whisper, id_or_json is the full JSON with word timestamps.
663	            // Save word-level JSON alongside the audio file.
664	            if matches!(job.method, TranscriptionMethod::LocalWhisper { .. }) {
665	                if let Err(e) = save_word_level_json(&job.audio_path, &id_or_json) {
666	                    eprintln!(
667	                        "[recordings] failed to save word-level JSON for {}: {}",
668	                        job.note_rel, e
669	                    );
670	                }
671	            }
672	
673	            let transcript_id = match &job.method {
674	                TranscriptionMethod::AssemblyAi { .. } => Some(id_or_json),
675	                TranscriptionMethod::LocalWhisper { .. } | TranscriptionMethod::Provider { .. } => {
676	                    None
677	                }
678	            };
679	
680	            if let Err(error) = update_recording_note_status(
681	                &job.note_path,
682	                RECORDING_STATUS_COMPLETED,
683	                None,
684	                transcript_id,
685	                Some(&transcript),
686	            ) {
687	                eprintln!(
688	                    "[recordings] failed to write transcript for {}: {}",
689	                    job.note_rel, error
690	                );
691	            }
692	        }
693	        Err(error) => {
694	            let _ = update_recording_note_status(
695	                &job.note_path,
696	                RECORDING_STATUS_FAILED,
697	                Some(error.clone()),
698	                None,
699	                None,
700	            );
701	            eprintln!(
702	                "[recordings] transcription failed for {}: {}",
703	                job.note_rel, error
704	            );
705	        }
706	    }
707	}
708	
709	/// Start a background worker thread if jobs are queued and none is running.
710	pub fn spawn_transcription_worker_if_needed() {
711	    let should_spawn = {
712	        let queue = transcription_queue_state();
713	        let mut state = queue.lock().expect("transcription queue poisoned");
714	        if state.running || state.pending.is_empty() {
715	            false
716	        } else {
717	            state.running = true;
718	            true
719	        }
720	    };
721	    if !should_spawn {
722	        return;
723	    }
724	    thread::spawn(move || loop {
725	        let maybe_job = {
726	            let queue = transcription_queue_state();
727	            let mut state = queue.lock().expect("transcription queue poisoned");
728	            match state.pending.pop_front() {
729	                Some(job) => {
730	                    state.current_recording = Some(job.note_rel.clone());
731	                    Some(job)
732	                }
733	                None => {
734	                    state.running = false;
735	                    state.current_recording = None;
736	                    None
737	                }
738	            }
739	        };
740	        let Some(job) = maybe_job else {
741	            break;
742	        };
743	        process_transcription_job(job.clone());
744	        let queue = transcription_queue_state();
745	        let mut state = queue.lock().expect("transcription queue poisoned");
746	        state.known_recordings.remove(&job.note_rel);
747	        if state.current_recording.as_deref() == Some(job.note_rel.as_str()) {
748	            state.current_recording = None;
749	        }
750	    });
751	}
752	
753	// ── Queue helpers ──────────────────────────────────────────────────────────────
754	
755	/// Queue all pending recordings for local whisper transcription (desktop only).
756	pub fn queue_recordings_for_local_transcription(
757	    app: &AppEnv,
758	    root: &Path,
759	    model: &str,
760	) -> Result<RecordingTranscriptionQueueResult, String> {
761	    queue_recordings_with_method(
762	        root,
763	        &TranscriptionMethod::LocalWhisper {
764	            model: model.to_string(),
765	            app: app.clone(),
766	        },
767	    )
768	}
769	
770	/// Queue all pending recordings for a shell-supplied [`TranscriptionProvider`]
771	/// (e.g. a native on-device recognizer registered through the mobile FFI).
772	pub fn queue_recordings_for_provider_transcription(
773	    root: &Path,
774	    provider: Arc<dyn TranscriptionProvider>,
775	) -> Result<RecordingTranscriptionQueueResult, String> {
776	    queue_recordings_with_method(root, &TranscriptionMethod::Provider { provider })
777	}
778	
779	/// Scan the recording notes under `root` and enqueue every transcribable one
780	/// with a clone of `method`; the shared sequential worker picks them up.
781	fn queue_recordings_with_method(
782	    root: &Path,
783	    method: &TranscriptionMethod,
784	) -> Result<RecordingTranscriptionQueueResult, String> {
785	    let recordings = collect_recording_notes(root)?;
786	    let active_recordings = active_transcription_note_paths();
787	    let mut scanned = 0usize;
788	    let mut skipped = 0usize;
789	    let mut candidates = Vec::new();
790	
791	    for recording in recordings {
792	        scanned += 1;
793	        if !recording.audio_path.exists() {
794	            let _ = update_recording_note_status(
795	                &recording.note_path,
796	                RECORDING_STATUS_FAILED,
797	                Some("Audio file is missing.".to_string()),
798	                None,
799	                None,
800	            );
801	            skipped += 1;
802	            continue;
803	        }
804	
805	        let status = recording.status.as_str();
806	        let is_active = active_recordings.contains(&recording.note_rel);
807	
808	        if status == RECORDING_STATUS_COMPLETED {
809	            skipped += 1;
810	            continue;
811	        }
812	
813	        if matches!(
814	            status,
815	            crate::RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
816	        ) && is_active
817	        {
818	            skipped += 1;
819	            continue;
820	        }
821	
822	        update_recording_note_status(
823	            &recording.note_path,
824	            crate::RECORDING_STATUS_QUEUED,
825	            None,
826	            None,
827	            None,
828	        )?;
829	        candidates.push(QueuedTranscriptionJob {
830	            note_rel: recording.note_rel,
831	            note_path: recording.note_path,
832	            audio_path: recording.audio_path,
833	            method: method.clone(),
834	        });
835	    }
836	
837	    let queued = {
838	        let queue = transcription_queue_state();
839	        let mut state = queue.lock().expect("transcription queue poisoned");
840	        let mut added = 0usize;
841	        for job in candidates {
842	            if state.known_recordings.contains(&job.note_rel) {
843	                continue;
844	            }
845	            state.known_recordings.insert(job.note_rel.clone());
846	            state.pending.push_back(job);
847	            added += 1;
848	        }
849	        added
850	    };
851	
852	    spawn_transcription_worker_if_needed();
853	    let in_flight = recording_queue_snapshot().in_flight;
854	
855	    Ok(RecordingTranscriptionQueueResult {
856	        scanned,
857	        queued,
858	        skipped,
859	        in_flight,
860	    })
861	}
862	
863	/// Reset a single recording's status and re-queue it for local transcription.
864	pub fn retrigger_single_transcription(
865	    app: &AppEnv,
866	    root: &Path,
867	    note_rel: &str,
868	    model: &str,
869	) -> Result<(), String> {
870	    let note_path = root.join(note_rel);
871	    if !note_path.exists() {
872	        return Err(format!("Note not found: {}", note_rel));
873	    }
874	    let raw = fs::read_to_string(&note_path).map_err(|e| e.to_string())?;
875	    let (meta, _) = parse_note_front_matter(&raw);
876	    let info = recording_info_from_note_meta(root, &note_path, note_rel, &meta)
877	        .ok_or_else(|| format!("Not a recording note: {}", note_rel))?;
878	
879	    if !info.audio_path.exists() {
880	        return Err("Audio file is missing.".to_string());
881	    }
882	
883	    // Reset status to queued
884	    update_recording_note_status(&note_path, crate::RECORDING_STATUS_QUEUED, None, None, None)?;
885	
886	    // Add to queue
887	    {
888	        let queue = transcription_queue_state();
889	        let mut state = queue.lock().expect("transcription queue poisoned");
890	        // Remove from known so it can be re-queued
891	        state.known_recordings.remove(note_rel);
892	        state.known_recordings.insert(note_rel.to_string());
893	        state.pending.push_back(QueuedTranscriptionJob {
894	            note_rel: note_rel.to_string(),
895	            note_path,
896	            audio_path: info.audio_path,
897	            method: TranscriptionMethod::LocalWhisper {
898	                model: model.to_string(),
899	                app: app.clone(),
900	            },
901	        });
902	    }
903	
904	    spawn_transcription_worker_if_needed();
905	    Ok(())
906	}
907	
908	// ── File allocation ────────────────────────────────────────────────────────────
909	
910	/// Default body for a newly created recording note (empty).
911	pub fn recording_initial_body() -> String {
912	    String::new()
913	}
914	
915	/// Generate a unique filename for a recording note.
916	pub fn recording_note_file_name(
917	    folder: &Path,
918	    timestamp_ms: i64,
919	    note_id: &str,
920	    file_name_format: NoteFileNameFormat,
921	) -> Result<String, String> {
922	    let fallback = format!("recording-{}", uuid_tail_without_timestamp_prefix(note_id));
923	    allocate_note_file_name(
924	        folder,
925	        timestamp_ms,
926	        note_id,
927	        "",
928	        &fallback,
929	        file_name_format,
930	    )
931	}
932	
933	/// Allocate a unique audio file path inside the Recordings storage folder.
934	pub fn recording_audio_file_path(root: &Path, extension: &str) -> Result<PathBuf, String> {
935	    let storage = recording_storage_root(root);
936	    fs::create_dir_all(&storage).map_err(|error| error.to_string())?;
937	    for _ in 0..=512usize {
938	        let candidate = storage.join(format!(
939	            "{}-{}.{}",
940	            AUDIO_FILE_NAME_PREFIX,
941	            Uuid::now_v7(),
942	            extension
943	        ));
944	        if !candidate.exists() {
945	            return Ok(candidate);
946	        }
947	    }
948	    Err("Failed to allocate recording audio filename.".to_string())
949	}
950	
951	/// Resolve the target folder for a new recording, falling back to Feed.
952	pub fn resolve_recording_target_folder(
953	    app: &AppEnv,
954	    requested: Option<&str>,
955	) -> Result<(String, PathBuf), String> {
956	    let root = notes_root(app)?;
957	    let candidate = requested.unwrap_or("").trim();
958	    if !candidate.is_empty() {
959	        let path = resolve_path(app, candidate)?;
960	        if path.exists() && path.is_dir() && !is_storage_folder_path(&root, &path) {
961	            return Ok((strip_root(&root, &path), path));
962	        }
963	    }
964	    let fallback = root.join(FEED_FOLDER);
965	    Ok((FEED_FOLDER.to_string(), fallback))
966	}
