1	import {
2	  createContext,
3	  useCallback,
4	  useContext,
5	  useEffect,
6	  useRef,
7	  useState,
8	  type ReactNode,
9	} from "react";
10	import * as api from "../api/recordings-api";
11	import type { RecordingListItem, RecordingQueueSnapshot } from "@typenotes/shared/types";
12	import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
13	import { toBase64, fromBase64 } from "@/shared/lib/notes";
14	import { useAudioRecorder } from "./use-audio-recorder";
15	import { useProfiles } from "@/features/profiles/hooks/profiles-context";
16	import { useAutoQueueLoop } from "@/features/processing/hooks/use-auto-queue-loop";
17	import { useProcessingQueue } from "@/features/processing/hooks/use-processing-queue";
18	import { jobListSignature } from "@typenotes/shared/jobs";
19	import { getErrorMessage } from "@typenotes/shared/errors";
20	
21	type RecordingsContextValue = {
22	  recordingSupported: boolean;
23	  isRecordingAudio: boolean;
24	  isRecordingFinalizing: boolean;
25	  recorderError: string | null;
26	  recordingElapsedLabel: string | null;
27	  recordingStatusMessage: string | null;
28	  transcriptionQueueBusy: boolean;
29	  recordingsQueue: RecordingQueueSnapshot | null;
30	  recordingsList: RecordingListItem[];
31	  recordingsBusy: boolean;
32	  recordingsError: string | null;
33	  activeAudioPath: string | null;
34	  activeAudioSrc: string | null;
35	  startRecording: (preferredFolderPath?: string | null) => void;
36	  stopRecording: () => void;
37	  refreshRecordings: () => Promise<void>;
38	  playRecording: (audioPath: string) => Promise<void>;
39	  queueRecordingTranscriptions: (trigger?: "manual" | "auto") => Promise<void>;
40	  retriggerTranscription: (notePath: string) => Promise<void>;
41	};
42	
43	const RecordingsContext = createContext<RecordingsContextValue | null>(null);
44	
45	export function RecordingsProvider({
46	  children,
47	  activeFolder,
48	  onRecordingComplete,
49	}: {
50	  children: ReactNode;
51	  activeFolder: string;
52	  onRecordingComplete: (result: {
53	    folder_path: string;
54	    note_path: string;
55	    audio_path: string;
56	  }) => Promise<void>;
57	}) {
58	  const { syncSettings } = useProfiles();
59	  const [recordingStatusMessage, setRecordingStatusMessage] = useState<string | null>(null);
60	  const [transcriptionQueueBusy, setTranscriptionQueueBusy] = useState(false);
61	  const [activeAudioPath, setActiveAudioPath] = useState<string | null>(null);
62	  const [activeAudioSrc, setActiveAudioSrc] = useState<string | null>(null);
63	
64	  const transcriptionQueueBusyRef = useRef(false);
65	  const recordingTargetFolderRef = useRef<string>(FEED_FOLDER_PATH);
66	  const activeAudioObjectUrlRef = useRef<string | null>(null);
67	
68	  const cleanupMissingActiveAudio = useCallback(
69	    (snapshot: { items: RecordingListItem[] }) => {
70	      if (!activeAudioPath) {
71	        return;
72	      }
73	      const stillExists = snapshot.items.some(
74	        (item) => item.audio_path === activeAudioPath
75	      );
76	      if (stillExists) {
77	        return;
78	      }
79	      if (activeAudioObjectUrlRef.current) {
80	        URL.revokeObjectURL(activeAudioObjectUrlRef.current);
81	        activeAudioObjectUrlRef.current = null;
82	      }
83	      setActiveAudioPath(null);
84	      setActiveAudioSrc(null);
85	    },
86	    [activeAudioPath]
87	  );
88	
89	  const loadRecordingsSnapshot = useCallback(async () => {
90	    const snapshot = await api.listRecordings();
91	    return {
92	      queue: snapshot.queue,
93	      items: snapshot.recordings,
94	    };
95	  }, []);
96	
97	  const {
98	    queue: recordingsQueue,
99	    items: recordingsList,
100	    busy: recordingsBusy,
101	    error: recordingsError,
102	    setError: setRecordingsError,
103	    refresh: refreshRecordings,
104	  } = useProcessingQueue<RecordingQueueSnapshot, RecordingListItem>({
105	    loadSnapshot: loadRecordingsSnapshot,
106	    getSignature: jobListSignature,
107	    invalidateEventName: "note-previews-invalidated",
108	    onSnapshotLoaded: cleanupMissingActiveAudio,
109	  });
110	
111	  const playRecording = useCallback(async (audioPath: string) => {
112	    try {
113	      const payload = await api.readRecordingAudio(audioPath);
114	      const bytes = fromBase64(payload.audio_base64);
115	      const blob = new Blob([bytes], {
116	        type: payload.mime_type || "audio/mpeg",
117	      });
118	      const objectUrl = URL.createObjectURL(blob);
119	      if (activeAudioObjectUrlRef.current) {
120	        URL.revokeObjectURL(activeAudioObjectUrlRef.current);
121	      }
122	      activeAudioObjectUrlRef.current = objectUrl;
123	      setActiveAudioPath(audioPath);
124	      setActiveAudioSrc(objectUrl);
125	      setRecordingsError(null);
126	    } catch (error) {
127	      const message = getErrorMessage(error);
128	      setRecordingsError(message);
129	    }
130	  }, []);
131	
132	  useEffect(
133	    () => () => {
134	      if (activeAudioObjectUrlRef.current) {
135	        URL.revokeObjectURL(activeAudioObjectUrlRef.current);
136	        activeAudioObjectUrlRef.current = null;
137	      }
138	    },
139	    []
140	  );
141	
142	  const queueRecordingTranscriptions = useCallback(
143	    async (trigger: "manual" | "auto" = "manual") => {
144	      if (transcriptionQueueBusyRef.current) {
145	        return;
146	      }
147	
148	      transcriptionQueueBusyRef.current = true;
149	      setTranscriptionQueueBusy(true);
150	      try {
151	        // Local whisper transcription — no API key needed.
152	        const result = await api.queueLocalTranscriptions(
153	          syncSettings.whisperModel.trim() || undefined
154	        );
155	        const label =
156	          trigger === "manual"
157	            ? `Scanned ${result.scanned}, queued ${result.queued}, in-flight ${result.in_flight}.`
158	            : `Auto queue: scanned ${result.scanned}, queued ${result.queued}.`;
159	        setRecordingStatusMessage(label);
160	      } catch (error) {
161	        const message = getErrorMessage(error);
162	        setRecordingStatusMessage(message);
163	      } finally {
164	        transcriptionQueueBusyRef.current = false;
165	        setTranscriptionQueueBusy(false);
166	        void refreshRecordings();
167	      }
168	    },
169	    [refreshRecordings, syncSettings.whisperModel]
170	  );
171	
172	  const retriggerTranscription = useCallback(
173	    async (notePath: string) => {
174	      try {
175	        await api.retriggerTranscription(
176	          notePath,
177	          syncSettings.whisperModel.trim() || undefined
178	        );
179	        setRecordingStatusMessage(`Re-queued ${notePath} for transcription.`);
180	        void refreshRecordings();
181	      } catch (error) {
182	        const message = getErrorMessage(error);
183	        setRecordingStatusMessage(`Retrigger failed: ${message}`);
184	      }
185	    },
186	    [refreshRecordings, syncSettings.whisperModel]
187	  );
188	
189	  const resolveRecordingTargetFolder = useCallback(
190	    (preferredFolderPath?: string | null) => {
191	      const preferred = preferredFolderPath?.trim();
192	      if (preferred) {
193	        return preferred;
194	      }
195	      const active = activeFolder.trim();
196	      return active || FEED_FOLDER_PATH;
197	    },
198	    [activeFolder]
199	  );
200	
201	  const handleRecordingReady = useCallback(
202	    async (blob: Blob, mimeType: string) => {
203	      const buffer = await blob.arrayBuffer();
204	      const audioBase64 = toBase64(new Uint8Array(buffer));
205	      const targetFolder = recordingTargetFolderRef.current || FEED_FOLDER_PATH;
206	      const result = await api.saveAudioRecording(
207	        audioBase64,
208	        mimeType || undefined,
209	        targetFolder,
210	        syncSettings.noteFileNameFormat
211	      );
212	      await onRecordingComplete(result);
213	      setRecordingStatusMessage(`Saved ${result.note_path}.`);
214	      void refreshRecordings();
215	      await queueRecordingTranscriptions("auto");
216	    },
217	    [
218	      onRecordingComplete,
219	      queueRecordingTranscriptions,
220	      refreshRecordings,
221	      syncSettings.noteFileNameFormat,
222	    ]
223	  );
224	
225	  const {
226	    isSupported: recordingSupported,
227	    isRecording: isRecordingAudio,
228	    isFinalizing: isRecordingFinalizing,
229	    error: recorderError,
230	    recordingElapsedLabel,
231	    startRecording: startRecordingRaw,
232	    stopRecording: stopRecordingRaw,
233	  } = useAudioRecorder({
234	    onRecordingReady: handleRecordingReady,
235	  });
236	
237	  const startRecording = useCallback(
238	    (preferredFolderPath?: string | null) => {
239	      recordingTargetFolderRef.current =
240	        resolveRecordingTargetFolder(preferredFolderPath);
241	      void startRecordingRaw();
242	    },
243	    [resolveRecordingTargetFolder, startRecordingRaw]
244	  );
245	
246	  const stopRecording = useCallback(() => {
247	    stopRecordingRaw();
248	  }, [stopRecordingRaw]);
249	
250	  const autoQueueTranscriptions = useCallback(
251	    () => queueRecordingTranscriptions("auto"),
252	    [queueRecordingTranscriptions]
253	  );
254	  useAutoQueueLoop({
255	    enabled: true,
256	    delayMs: 0,
257	    onTick: autoQueueTranscriptions,
258	  });
259	
260	  return (
261	    <RecordingsContext.Provider
262	      value={{
263	        recordingSupported,
